import{_ as a,o,c as r,a5 as i}from"./chunks/framework.BwlBv862.js";const u=JSON.parse('{"title":"Registro da candidata TikTools 4.2.1-rc.2","description":"","frontmatter":{"title":"Registro da candidata TikTools 4.2.1-rc.2","docId":"releases.4.2.1-rc.2","translationKey":"releases.4.2.1-rc.2","locale":"pt","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"af1ea83a9bb29fd23f3e4c086d976fb5abecaff8e20965cc6db9b5c64d5b191e","translationRevision":"35523ebacaab53441f13067fe626fc076f084b518f1450fa4518f4ee28f04f2e","order":20},"headers":[],"relativePath":"pt/releases/4.2.1-rc.2.md","filePath":"pt/releases/4.2.1-rc.2.md","lastUpdated":1794611623000}'),t={name:"pt/releases/4.2.1-rc.2.md"};function s(d,e,c,n,l,p){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="tiktools-421-rc2" tabindex="-1">TikTools 4.2.1-rc.2 <a class="header-anchor" href="#tiktools-421-rc2" aria-label="Permalink to &quot;TikTools 4.2.1-rc.2 {#tiktools-421-rc2}&quot;">​</a></h1><h2 id="goal-status-and-prerequisites" tabindex="-1">Objetivo, status e pré-requisitos <a class="header-anchor" href="#goal-status-and-prerequisites" aria-label="Permalink to &quot;Objetivo, status e pré-requisitos {#goal-status-and-prerequisites}&quot;">​</a></h2><p>Use as notas históricas da RC2 para entender a correção das leituras concorrentes de Changes reproduzidas na RC1. O registro da candidata cobre pacotes Linux AppImage, DEB e portáteis compilados localmente enquanto Actions estava desativado. Ele não comprova disponibilidade atual de download nem um pacote Windows recém-compilado. Escolha artefatos na <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">lista de versões</a>, guarde seu arquivo de somas de verificação e teste com um perfil isolado.</p><p>Recuperação do Cloud e colaboração continuam experimentais. A busca por apelido ainda depende do backend <code>6a69c99</code> e da migração <code>20261113000001_remote_invitation_recipients.sql</code>; o pacote do aplicativo não implanta essas alterações.</p><h2 id="correction-and-expected-behavior" tabindex="-1">Correção e comportamento esperado <a class="header-anchor" href="#correction-and-expected-behavior" aria-label="Permalink to &quot;Correção e comportamento esperado {#correction-and-expected-behavior}&quot;">​</a></h2><p>Listas de Changes/conflitos e seleção de protocolo compartilham a observação de protocolo em vez de reservar o espaço de mutação do produto. Leituras da barra de ferramentas e do painel podem concluir enquanto uma operação não relacionada do diário de pacotes ocupa esse espaço. Barreiras de gravação, isolamento de contas e decisões explícitas de migração permanecem.</p><p>A verificação de conta rejeita saída da conta, transições pendentes e sessões substitutas. Ler uma comparação local não restaura credenciais nem inicia uma requisição ao Cloud. Em falha, a interface mostra o motivo nativo e uma ação de recarga local; essa nova tentativa não envia, baixa nem resolve um registro.</p><h2 id="check-the-candidate" tabindex="-1">Verifique a candidata <a class="header-anchor" href="#check-the-candidate" aria-label="Permalink to &quot;Verifique a candidata {#check-the-candidate}&quot;">​</a></h2><ol><li>Registre a versão exibida <code>4.2.1-rc.2</code> e abra Plugins → Changes em um perfil isolado.</li><li>Abra ou recarregue a comparação pela barra de ferramentas e pelo painel. Uma falha de carregamento deve manter seu motivo em vez de informar que tudo está sincronizado.</li><li>Use a nova tentativa local e confirme que ela recarrega a comparação sem alterar filas pendentes nem aplicar registros remotos.</li><li>Registre transições de conta/sessão separadamente. Compare com o <a href="./4.2.1-rc.1.html">procedimento de migração da RC1</a> ao reproduzir um perfil afetado.</li></ol><h2 id="recorded-validation-and-recovery" tabindex="-1">Validação registrada e recuperação <a class="header-anchor" href="#recorded-validation-and-recovery" aria-label="Permalink to &quot;Validação registrada e recuperação {#recorded-validation-and-recovery}&quot;">​</a></h2><p>O registro original descreve uma regressão determinística com 32 leitores, verificações de CloudAuth/sincronização/nativo/frontend e inicialização do AppImage otimizado com perfil isolado vazio. Verificações de conteúdo do instalador e arquivo portátil foram registradas. Essa inicialização não testou sincronização autenticada em produção nem reprodução de mídia.</p><p>O SHA-256 histórico do AppImage era <code>35fc26e7bc5875c5a3fe99bf6a84baf77af8ca63d1c8b8e61825881187d6091f</code>. Ele identifica aquele arquivo registrado; use a soma de verificação anexada ao artefato que realmente baixar.</p><p>Se o carregamento ainda falhar, guarde versão, erro nativo e ID da requisição e use <a href="./../user/preferences/troubleshooting.html">Diagnostics</a>. Preserve edições e conflitos pendentes. Na RC2, Automations ainda usava referência local, o trabalho nas seções Variables e Overlays estava inacabado e o detentor histórico do bloqueio SQLite permanecia não identificado. Estas notas não afirmam que a rota ausente de busca de pessoas de um backend antigo tenha sido implantada desde então.</p><p>O <a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.1-rc.2.md" target="_blank" rel="noreferrer">registro original da versão</a> é mantido como evidência datada. Volte ao <a href="./">índice de versões</a>.</p>',14)])])}const f=a(t,[["render",s]]);export{u as __pageData,f as default};
